(async()=>{const b=Uint8Array.from(atob(""),c=>c.charCodeAt(0));const html=await new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip'))).text();window.__PRE_PANEL_HTML=html;setInterval(()=>{const f=document.getElementById('pre-integrated-frame');if(f&&!f.dataset.loaded){f.dataset.loaded='1';f.srcdoc=html;}},250);})();